\set ON_ERROR_STOP on
begin;
create schema test;
create function test.assert(ok boolean,message text) returns void language plpgsql as $$begin if not coalesce(ok,false) then raise exception 'FAIL: %',message;end if;raise notice 'PASS: %',message;end$$;
create function test.reject(statement text,pattern text,message text) returns void language plpgsql as $$declare failed boolean:=false;begin begin execute statement;exception when others then if position(pattern in sqlerrm)=0 then raise exception 'Unexpected failure for %: %',message,sqlerrm;end if;failed:=true;end;if not failed then raise exception 'FAIL: % accepted forbidden operation',message;end if;raise notice 'PASS: %',message;end$$;
grant usage on schema test to authenticated;grant execute on all functions in schema test to authenticated;
insert into auth.users(id,email) values('00000000-0000-0000-0000-000000000001','owner@example.test'),('00000000-0000-0000-0000-000000000002','finance@example.test'),('00000000-0000-0000-0000-000000000003','employee@example.test'),('00000000-0000-0000-0000-000000000004','manager@example.test'),('00000000-0000-0000-0000-000000000005','hr@example.test'),('00000000-0000-0000-0000-000000000006','admin@example.test'),('00000000-0000-0000-0000-000000000007','other@example.test');
