select test.assert((select sum(days)=3 from public.leave_ledger),'Reviewed cancellation reverses balance');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
select test.reject($$select public.command('approve_expense','30000000-0000-0000-0000-000000000002',1,'{"reason":"Own claim"}')$$,'Independent CEO','Owner self-approval blocked');
select public.command('approve_expense','30000000-0000-0000-0000-000000000001',1,'{"reason":"Quote reviewed"}');
