select test.reject($$select public.command('record_payment','30000000-0000-0000-0000-000000000001',2,'{"amount":"70.00","reference":"PAY-2","evidence":"Bank receipt"}')$$,'remaining approval','Overpayment rejected');
select test.reject($$select public.command('record_payment','30000000-0000-0000-0000-000000000001',2,'{"amount":"10.00","reference":"PAY-1","evidence":"Bank receipt"}')$$,'unique constraint','Duplicate payment reference rejected');
select public.command('record_payment','30000000-0000-0000-0000-000000000001',2,'{"amount":"60.00","reference":"PAY-2","evidence":"Bank receipt"}');
select public.command('reconcile_expense','30000000-0000-0000-0000-000000000001',2,'{"evidence":"Statement matched"}');
select test.assert((select sum(amount)=100 from public.payments),'Exact partial payments total approval');
select test.reject($$select public.command('create_journal',null,null,'{"period_id":"80000000-0000-0000-0000-000000000001","entry_date":"2026-10-13","description":"Bad journal","source_reference":"BAD-1","lines":[{"account_id":"70000000-0000-0000-0000-000000000001","debit":100},{"account_id":"70000000-0000-0000-0000-000000000002","credit":99}]}')$$,'Balanced journal','Unbalanced journal rejected atomically');
select test.assert((select count(*)=0 from public.journals),'Failed journal rolled back');
select public.command('create_journal',null,null,'{"period_id":"80000000-0000-0000-0000-000000000001","entry_date":"2026-10-13","description":"Receipt posting","source_reference":"GOOD-1","lines":[{"account_id":"70000000-0000-0000-0000-000000000001","debit":100},{"account_id":"70000000-0000-0000-0000-000000000002","credit":100}]}');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
select public.command('approve_journal',(select id from public.journals where source_reference='GOOD-1'),1,'{}');
