select test.assert((select state='posted' from public.journals where source_reference='GOOD-1'),'Balanced approved journal posted');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000006',true);
select test.assert((select count(*)=0 from public.expenses),'Admin has no unrestricted finance access');
select test.assert((select count(*)=0 from public.compensation_proposals),'Admin has no compensation access');
reset role;
select test.reject($$update public.journals set description='Rewrite' where source_reference='GOOD-1'$$,'immutable','Posted journal cannot be rewritten');
select test.reject($$update public.journal_lines set debit=90 where debit=100$$,'immutable','Posted journal lines cannot be rewritten');
select test.reject($$delete from public.user_roles where role='ceo'$$,'last active owner','Last active CEO protected');
