insert into public.journal_lines(journal_id,account_id,debit,credit) values('40000000-0000-0000-0000-000000000002','70000000-0000-0000-0000-000000000001',100,0),('40000000-0000-0000-0000-000000000002','70000000-0000-0000-0000-000000000002',0,100);
-- Line changes correctly invalidate approval; reapprove the fixed test version as trusted setup.
update public.journals set state='approved',approved_version=version where source_reference='LOCKED-1';
set local role authenticated;
