select test.reject($$update public.performance_reviews set score=100$$,'immutable','Finalized review cannot be silently edited');
-- Material expense changes must remove version-specific approval.
insert into public.expenses(id,submitted_by,payee,purpose,category,amount,evidence,approval_status,approved_by,approved_version,approved_amount) values('30000000-0000-0000-0000-000000000003','00000000-0000-0000-0000-000000000002','Supplier','Original','Office',50,'Quote','approved','00000000-0000-0000-0000-000000000001',1,50);
