reset role;
do $$declare tbl text;begin
 for tbl in select tablename from pg_tables where schemaname='public' loop
  perform test.assert((select relrowsecurity from pg_class where oid=('public.'||quote_ident(tbl))::regclass),'RLS enabled: '||tbl);
  perform test.assert(not has_table_privilege('authenticated','public.'||quote_ident(tbl),'INSERT'),'Direct INSERT denied: '||tbl);
  perform test.assert(not has_table_privilege('authenticated','public.'||quote_ident(tbl),'UPDATE'),'Direct UPDATE denied: '||tbl);
  perform test.assert(not has_table_privilege('authenticated','public.'||quote_ident(tbl),'DELETE'),'Direct DELETE denied: '||tbl);
  perform test.assert(not has_table_privilege('anon','public.'||quote_ident(tbl),'SELECT'),'Anonymous SELECT denied: '||tbl);
 end loop;
end $$;
