select test.assert((select active_seconds=(select n from t_att2)+165 from public.attendance where employee_id='00000000-0000-0000-0000-000000000007'),'Offline minutes are added to the attendance record they fall in');
update public.agent_devices set last_seen_at=now()-interval '30 seconds' where id=(select id from t_dev2);
select test.assert((public.agent_heartbeat((select r->>'token' from t_pair2),jsonb_build_object('state','idle','active_seconds',0,'backlog',jsonb_build_array(jsonb_build_object('minute',now()-interval '2 hours','seconds',60))))->>'backlog_credited')::integer=0,'Sending the same minute again credits nothing');
insert into public.work_breaks(user_id,started_at,ends_at,ended_at,end_reason) values('00000000-0000-0000-0000-000000000007',now()-interval '5 hours',now()-interval '4 hours 50 minutes',now()-interval '4 hours 50 minutes','finished');
update public.agent_devices set last_seen_at=now()-interval '30 seconds' where id=(select id from t_dev2);
select test.assert((public.agent_heartbeat((select r->>'token' from t_pair2),jsonb_build_object('state','idle','active_seconds',0,'backlog',jsonb_build_array(jsonb_build_object('minute',now()-interval '4 hours 55 minutes','seconds',60))))->>'backlog_credited')::integer=0,'Offline minutes that fall inside a break are not credited');
-- Changing a project's leader, and deleting a project.
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000004',true);
select set_config('request.jwt.claims','{"aal":"aal2","session_id":"aaaaaaaa-0000-0000-0000-000000000006"}',true);
select test.reject($$select public.command('set_project_leader',(select id from public.projects where name='CEO assigned'),(select version from public.projects where name='CEO assigned'),'{"leader_id":"00000000-0000-0000-0000-0000000000ff"}')$$,'active manager','Only an active employee can become project leader');
select test.reject($$select public.command('set_project_leader',(select id from public.projects where name='CEO assigned'),(select version from public.projects where name='CEO assigned'),'{"leader_id":"00000000-0000-0000-0000-000000000004"}')$$,'already the project leader','Choosing the current leader is refused');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',true);
select set_config('request.jwt.claims','{"aal":"aal2"}',true);
select test.reject($$select public.command('set_project_leader',(select id from public.projects where name='CEO assigned'),(select version from public.projects where name='CEO assigned'),'{"leader_id":"00000000-0000-0000-0000-000000000001"}')$$,'CEO or the project leader','Someone who is not the leader or CEO cannot change the leader');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000004',true);
select set_config('request.jwt.claims','{"aal":"aal2","session_id":"aaaaaaaa-0000-0000-0000-000000000006"}',true);
select public.command('set_project_leader',(select id from public.projects where name='CEO assigned'),(select version from public.projects where name='CEO assigned'),'{"leader_id":"00000000-0000-0000-0000-000000000001"}');
select test.assert((select manager_id='00000000-0000-0000-0000-000000000001' from public.projects where name='CEO assigned'),'The leader hands the project to a new leader');
select test.assert(exists(select 1 from public.notifications where user_id='00000000-0000-0000-0000-000000000001' and title like 'You are now the leader%'),'The new leader is notified');
select test.reject($$select public.command('delete_project',(select id from public.projects where name='CEO assigned'),(select version from public.projects where name='CEO assigned'),'{"reason":"Not mine any more"}')$$,'CEO or the project leader','The former leader can no longer delete the project');
set local role authenticated;
select test.assert((select count(*)=0 from public.tasks where title='Visibility task'),'The former leader no longer sees the tasks of the project');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
select set_config('request.jwt.claims','{"aal":"aal2"}',true);
select test.assert((select count(*)=2 from public.tasks where title='Visibility task'),'The new leader sees every task');
reset role;
-- Delete a project that has no completed work.
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000004',true);
select set_config('request.jwt.claims','{"aal":"aal2","session_id":"aaaaaaaa-0000-0000-0000-000000000006"}',true);
select public.command('create_project',null,null,'{"leader_id":"00000000-0000-0000-0000-000000000004","name":"To delete","due_date":"2026-12-01"}');
select public.command('create_task',null,null,format('{"project_id":"%s","title":"Doomed task","acceptance_criteria":"Done","weight":3,"due_date":"2026-12-31","assignees":[{"id":"00000000-0000-0000-0000-000000000007"}]}',(select id from public.projects where name='To delete'))::jsonb);
select test.reject($$select public.command('delete_project',(select id from public.projects where name='To delete'),(select version from public.projects where name='To delete'),'{"reason":"x"}')$$,'Reason required','Deleting needs a reason');
select public.command('delete_project',(select id from public.projects where name='To delete'),(select version from public.projects where name='To delete'),'{"reason":"Duplicate project"}');
select test.assert((select deleted_at is not null and status='cancelled' from public.projects where name='To delete'),'The project is marked deleted');
select test.assert((select status='cancelled' from public.tasks where title='Doomed task'),'Its open tasks are cancelled');
select test.assert((select count(*)=1 from public.task_history h join public.tasks t on t.id=h.task_id where t.title='Doomed task' and h.reason='Project deleted: Duplicate project'),'The cancellation is kept in task history');
set local role authenticated;
select test.assert((select count(*)=0 from public.projects where name='To delete') and (select count(*)=0 from public.tasks where title='Doomed task'),'The leader no longer sees the deleted project or its tasks');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000007',true);
select set_config('request.jwt.claims','{"aal":"aal1"}',true);
select test.assert((select count(*)=0 from public.projects where name='To delete') and (select count(*)=0 from public.tasks where title='Doomed task'),'The assignee no longer sees the deleted project or its tasks');
reset role;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000004',true);
select set_config('request.jwt.claims','{"aal":"aal2","session_id":"aaaaaaaa-0000-0000-0000-000000000006"}',true);
select test.reject($$select public.command('delete_project',(select id from public.projects where name='Test project'),(select version from public.projects where name='Test project'),'{"reason":"Cleaning up"}')$$,'Only the CEO can delete it','A project leader cannot delete a project that has work records');
-- The CEO can delete a project that has work records, after typing its name; the records stay.
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
select set_config('request.jwt.claims','{"aal":"aal2"}',true);
select test.reject($$select public.command('delete_project',(select id from public.projects where name='Test project'),(select version from public.projects where name='Test project'),'{"reason":"Old test project"}')$$,'Type the project name','Deleting a project with work records needs the name typed');
select test.reject($$select public.command('delete_project',(select id from public.projects where name='Test project'),(select version from public.projects where name='Test project'),'{"reason":"Old test project","confirm_name":"Another project"}')$$,'Type the project name','A wrong name is refused');
create temp table t_logs as select count(*) as n from public.work_logs;
create temp table t_done as select count(*) as n from public.tasks where status='completed' and project_id=(select id from public.projects where name='Test project');
select public.command('delete_project',(select id from public.projects where name='Test project'),(select version from public.projects where name='Test project'),'{"reason":"Old test project","confirm_name":"test PROJECT"}');
select test.assert((select deleted_at is not null from public.projects where name='Test project'),'The CEO deleted the project that had work records');
select test.assert((select count(*)=(select n from t_logs) from public.work_logs),'No work log was removed');
select test.assert((select count(*)=(select n from t_done) from public.tasks where status='completed' and project_id=(select id from public.projects where name='Test project')),'Completed tasks stay completed');
select test.assert((select count(*)=0 from public.tasks where project_id=(select id from public.projects where name='Test project') and status not in ('completed','cancelled')),'Open tasks of the project are cancelled');
select test.assert(exists(select 1 from public.audit_events where event='project_deleted' and details->>'had_work_records'='true'),'The deletion is audited with the fact that it had records');
set local role authenticated;
select test.assert((select count(*)=0 from public.projects where name='Test project'),'The deleted project is hidden from the CEO too');
reset role;
rollback;
